@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_create_user(api_client, petstore_auth, api_key, scenario_case):
    """
    Test the creation of a user with various scenarios.
    """
    endpoint = "/user"
    method = "POST"
    headers = {
        "Authorization": f"Bearer {petstore_auth}",
        "Content-Type": "application/json"
    }
    data = {
        "id": scenario_case.get("id"),
        "username": scenario_case.get("username"),
        "firstName": scenario_case.get("firstName"),
        "lastName": scenario_case.get("lastName"),
        "email": scenario_case.get("email"),
        "password": scenario_case.get("password"),
        "phone": scenario_case.get("phone"),
        "userStatus": scenario_case.get("userStatus")
    }

